// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(address caller) public {
        bool ok;
        string memory v;
        bytes memory payload = abi.encodeWithSelector(bytes4(keccak256("version()")));
        vm.prank(caller);
        (bool success, bytes memory ret) = address(c).call(payload);
        if (success) {
            v = abi.decode(ret, (string));
            ok = bytes(v).length != 0;
        } else {
            ok = false;
        }

        assertTrue(ok);
    }
}
